<script>(()=>{const status=document.getElementById('driver-connection'),notice=document.getElementById('connection-required');const update=()=>{if(!status)return;status.textContent=navigator.onLine?'Con conexión':'Sin conexión';status.dataset.offline=String(!navigator.onLine)};addEventListener('online',update);addEventListener('offline',update);update();document.addEventListener('submit',event=>{if(!navigator.onLine){event.preventDefault();notice?.classList.add('visible');setTimeout(()=>notice?.classList.remove('visible'),5000)}});@if($centralDriver)if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('{{ route('driver.service-worker') }}',{scope:'/driver/'});let deferredPrompt=null;const install=document.getElementById('install-driver'),standaloneMedia=matchMedia('(display-mode: standalone)'),isInstalledMode=()=>standaloneMedia.matches||window.navigator.standalone===true,hideInstall=()=>{deferredPrompt=null;if(install)install.hidden=true};if(isInstalledMode())hideInstall();addEventListener('beforeinstallprompt',event=>{if(typeof event.prompt!=='function')return;event.preventDefault();if(isInstalledMode()){hideInstall();return}deferredPrompt=event;if(install)install.hidden=false});install?.addEventListener('click',async()=>{if(isInstalledMode()||!deferredPrompt||typeof deferredPrompt.prompt!=='function'){hideInstall();return}const currentPrompt=deferredPrompt;try{await currentPrompt.prompt();await currentPrompt.userChoice}catch(error){@unless(app()->environment('production'))console.warn('No fue posible abrir la instalación de ZIGO Driver.',error);@endunless}finally{hideInstall()}});standaloneMedia.addEventListener?.('change',event=>{if(event.matches)hideInstall()});addEventListener('appinstalled',hideInstall);@endif})();</script></body></html>
